#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    string getSmallestString(int n, int k) {
        string res(n, 'a');
        int rem = k - n;
        int i = n - 1;
        while (rem > 0) {
            int add = min(25, rem);
            res[i] += add;
            rem -= add;
            i--;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String getSmallestString(int n, int k) {
        char[] res = new char[n];
        Arrays.fill(res, 'a');
        int rem = k - n;
        int i = n - 1;
        while (rem > 0) {
            int add = Math.min(25, rem);
            res[i] = (char)('a' + add);
            rem -= add;
            i--;
        }
        return new String(res);
    }
}

/**
 * @param {number} n
 * @param {number} k
 * @return {string}
 */
var getSmallestString = function(n, k) {
    const res = Array(n).fill('a');
    let rem = k - n;
    let i = n - 1;
    while (rem > 0) {
        const add = Math.min(25, rem);
        res[i] = String.fromCharCode(97 + add);
        rem -= add;
        i--;
    }
    return res.join('');
};
